"""Index only completed original F1 outputs; no inference/parser/gold/evaluator reexecution."""
from pathlib import Path
import json,hashlib,datetime,os
F=Path(__file__).parent;Q=F/'quality'
def read(p):return json.loads(Path(p).read_text())
def ref(p):p=Path(p);return dict(path=str(p),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest())
def checked(r):assert {k:ref(r['path'])[k] for k in ['bytes','sha256']}=={k:r[k] for k in ['bytes','sha256']}
def save(p,x):
 with p.open('x') as f:json.dump(x,f,indent=2,ensure_ascii=False);f.write('\n');f.flush();os.fsync(f.fileno())
