result=read(F/'recovered/terminal/result.json');wrapper=read(F/'recovered/wrapper-result.json');assert result['status']=='COMPLETE_FIXED80_RESPONSES_2_REUSED_78_NEW_NO_QUALITY_EVALUATION' and result['new_generations']==78 and result['reused_generations']==2 and len(result['rows'])==80
assert wrapper['returncode']==0 and wrapper['result_sha256']==ref(F/'recovered/terminal/result.json')['sha256'] and wrapper['target_UUID_has_no_compute_process'] is True
paths=[F/'finish-controller-intent.json',F/'finish-controller-complete.json',F/'finish-collect-complete.json',F/'finish-bind-complete.json',F/'finish-evaluate-complete.json',F/'plan.json',F/'entry-manifest.json',F/'evaluation-plan.json',F/'evaluation-template.json',F/'evaluate_full80.py',F/'full80_contract.py',F/'infer_full80.py',F/'launch_full80.py',F/'normalized_final.py',F/'strict_final.py',F/'sparse_final.py',F/'response-collection.json',F/'recovered/collection-manifest.json',F/'recovered/wrapper-result.json',F/'recovered/terminal/result.json',Q/'summary.json',Q/'paired-predictions-freeze.json',Q/'evaluation-started.json',F/'freeze_terminal.py']
for name in ['primary-r1','secondary-union']:
 e=summary['endpoints'][name];checked(e['metrics_file']);checked(e['format_file']);checked(freeze['endpoints'][name]['prediction']);assert read(e['format_file']['path'])['valid'];assert read(e['metrics_file']['path'])['metrics']==e['metrics'];paths.extend([Path(e['metrics_file']['path']),Path(e['format_file']['path']),Path(freeze['endpoints'][name]['prediction']['path'])])
paths.extend([Path(summary['old_cached_metrics']['path'])]);checked(summary['old_cached_metrics'])
manifest={'status':'COMPLETE_ORIGINAL_FIXED80_TWO_ENDPOINTS_FROZEN_NO_NEW_QUALITY_CALL','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':[ref(p) for p in paths],'original_H49_scope':'Original live source preserved; this actual complete80 terminal and canonical row bindings passed. This does not repair the old source for future unexpected parser exceptions.','original_policy_unchanged':summary['policy'],'new_v2_calls':summary['new_v2_calls'],'old_metrics_reused':True,'fresh_generations':78,'reused_generations':2,'actual_wrapper_seconds':wrapper['GPU_main_seconds'],'actual_release':wrapper['actual_release'],'coverage':result.get('coverage'),'quality_summary':ref(Q/'summary.json'),'independent_F0_successor_condition_is_separate_not_original_F1_plan':True}
save(F/'terminal-manifest.json',manifest);print(json.dumps({'manifest':ref(F/'terminal-manifest.json'),'old':summary['old_metrics'],'endpoints':{k:{'metrics':v['metrics'],'delta':v['delta_vs_old'],'original_retain':v['retain_vs_old_advisory']} for k,v in summary['endpoints'].items()},'coverage':result.get('coverage'),'seconds':wrapper['GPU_main_seconds']}))
